from collections import deque

graph = {'A': ['B', 'C'], 'B': ['D', 'E'], 'C': ['F'],
         'D': [], 'E': ['G'], 'F': ['G'], 'G': []}
frontier = deque(['A'])
visited = {'A'}
while frontier:
    node = frontier.popleft()
    print(node, end=' ')
    if node == 'G':
        break
    for nxt in graph[node]:
        if nxt not in visited:
            visited.add(nxt)
            frontier.append(nxt)

